export function checksum(text) {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}

export function classify(level) {
  switch (level) {
    case 4: return 40;
    case 5: return 50;
    case 6: return 60;
    default: return -1;
  }
}
